@import "tailwindcss";

:root {
	--bg: #0a0e14;
	--panel: #10141d;
	--panel-2: #151b27;
	--border: #1e2635;
	--border-strong: #2a3548;
	--text: #e6eaf2;
	--text-dim: #8b95a9;
	--text-faint: #5c6577;
	--accent: #38bdf8;
	--up: #34d399;
	--down: #f87171;
	--gold: #fbbf24;
	--violet: #a78bfa;
}

* {
	box-sizing: border-box;
}

html,
body {
	background: var(--bg);
	color: var(--text);
	font-family:
		"Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
	-webkit-font-smoothing: antialiased;
}

.font-mono,
.tabular {
	font-family:
		"JetBrains Mono", ui-monospace, "SF Mono", SFMono-Regular, Menlo, monospace;
	font-variant-numeric: tabular-nums;
}

/* Scrollbars */
::-webkit-scrollbar {
	width: 8px;
	height: 8px;
}
::-webkit-scrollbar-track {
	background: transparent;
}
::-webkit-scrollbar-thumb {
	background: var(--border-strong);
	border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
	background: #3a4a63;
}

/* Panels & cards */
.panel {
	background: var(--panel);
	border: 1px solid var(--border);
	border-radius: 10px;
}
.panel-2 {
	background: var(--panel-2);
	border: 1px solid var(--border);
	border-radius: 8px;
}

/* Ticker flash for live updates */
@keyframes flash-up {
	from {
		background-color: rgba(52, 211, 153, 0.18);
	}
	to {
		background-color: transparent;
	}
}
@keyframes flash-down {
	from {
		background-color: rgba(248, 113, 113, 0.18);
	}
	to {
		background-color: transparent;
	}
}
.flash-up {
	animation: flash-up 1.2s ease-out;
}
.flash-down {
	animation: flash-down 1.2s ease-out;
}

/* Blinking cursor for terminal aesthetics */
@keyframes blink {
	50% {
		opacity: 0;
	}
}
.cursor-blink {
	animation: blink 1.1s step-end infinite;
}

/* Skeleton loading */
@keyframes shimmer {
	0% {
		background-position: -400px 0;
	}
	100% {
		background-position: 400px 0;
	}
}
.skeleton {
	background: linear-gradient(
		90deg,
		var(--panel-2) 25%,
		#1b2333 37%,
		var(--panel-2) 63%
	);
	background-size: 800px 100%;
	animation: shimmer 1.4s infinite linear;
	border-radius: 6px;
}

/* Focus rings */
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
button:focus-visible {
	outline: 2px solid var(--accent);
	outline-offset: 1px;
}

/* Subtle grid texture on hero panels */
.grid-texture {
	background-image:
		linear-gradient(rgba(56, 189, 248, 0.03) 1px, transparent 1px),
		linear-gradient(90deg, rgba(56, 189, 248, 0.03) 1px, transparent 1px);
	background-size: 32px 32px;
}

