"use client";

import { useMemo, useState } from "react";
import { api, type SentimentFeed } from "@/lib/api";
import { usePolling } from "@/lib/usePolling";
import Shell from "@/components/Shell";
import { SectionHeader, Skeleton, StatCard } from "@/components/ui";

const CATEGORY_ORDER = ["WHALE", "KINERJA", "ACTION", "KOMODITAS", "GLOBAL"];

export default function SentimentPage() {
	const [category, setCategory] = useState<string>("ALL");
	const [tag, setTag] = useState<string>("ALL");
	const feed = usePolling<SentimentFeed>(
		() => api.get("/api/sentiment/news"),
		300000,
	);

	const items = useMemo(() => {
		if (!feed.data) return [];
		let out = feed.data.items;
		if (category !== "ALL") out = out.filter((i) => i.category === category);
		if (tag !== "ALL") out = out.filter((i) => i.tags.includes(tag));
		return out;
	}, [feed.data, category, tag]);

	const allTags = useMemo(() => {
		const set = new Set<string>();
		feed.data?.items.forEach((i) => i.tags.forEach((t) => set.add(t)));
		return [...set].sort();
	}, [feed.data]);

	const counts = useMemo(() => {
		const c: Record<string, number> = {};
		feed.data?.items.forEach((i) => {
			c[i.category] = (c[i.category] ?? 0) + 1;
		});
		return c;
	}, [feed.data]);

	return (
		<Shell>
			<SectionHeader
				title="Sentiment Radar"
				subtitle="Weekly market intelligence from Kontan, Bisnis, CNBC Indonesia, Investor.id — whale & insider, financials, corporate action, commodities"
				right={
					<button
						onClick={() => void feed.refresh()}
						className="rounded-md bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-black hover:opacity-90"
					>
						Rescan News
					</button>
				}
			/>

			<div className="mb-6 grid grid-cols-2 gap-4 lg:grid-cols-4">
				<StatCard
					label="Total Headlines"
					value={feed.data?.count ?? "…"}
					tone="accent"
				/>
				<StatCard label="Whale / Insider" value={counts.WHALE ?? 0} tone="up" />
				<StatCard
					label="Financials"
					value={counts.KINERJA ?? 0}
					tone="accent"
				/>
				<StatCard
					label="Corporate Action"
					value={counts.ACTION ?? 0}
					tone="accent"
				/>
			</div>

			<div className="mb-4 flex flex-wrap items-center gap-2">
				<button
					onClick={() => setCategory("ALL")}
					className={`rounded-md px-3 py-1.5 text-xs font-semibold ${
						category === "ALL"
							? "bg-[var(--panel-2)] text-[var(--accent)] ring-1 ring-[var(--accent)]"
							: "text-[var(--text-dim)] hover:bg-[var(--panel-2)]"
					}`}
				>
					All
				</button>
				{CATEGORY_ORDER.map((c) => (
					<button
						key={c}
						onClick={() => setCategory(c)}
						className={`rounded-md px-3 py-1.5 text-xs font-semibold ${
							category === c
								? "bg-[var(--panel-2)] text-[var(--accent)] ring-1 ring-[var(--accent)]"
								: "text-[var(--text-dim)] hover:bg-[var(--panel-2)]"
						}`}
					>
						{c}
					</button>
				))}
				<select
					value={tag}
					onChange={(e) => setTag(e.target.value)}
					className="panel-2 ml-auto px-3 py-1.5 text-xs text-[var(--text)] focus:outline-none"
				>
					<option value="ALL">All topics</option>
					{allTags.map((t) => (
						<option key={t} value={t}>
							{t}
						</option>
					))}
				</select>
			</div>

			{feed.loading && !feed.data ? (
				<div className="grid grid-cols-1 gap-4 md:grid-cols-2">
					{[0, 1, 2, 3, 4, 5].map((i) => (
						<Skeleton key={i} className="h-32" />
					))}
				</div>
			) : items.length === 0 ? (
				<div className="panel p-16 text-center text-sm text-[var(--text-faint)]">
					No headlines for this filter — rescan to fetch the latest feed.
				</div>
			) : (
				<div className="grid grid-cols-1 gap-4 md:grid-cols-2">
					{items.map((item, i) => (
						<a
							key={`${item.link}-${i}`}
							href={item.link}
							target="_blank"
							rel="noreferrer"
							className="panel block p-4 transition-colors hover:border-[var(--border-strong)]"
							style={{ borderLeft: `3px solid ${item.color}` }}
						>
							<div className="mb-1 flex items-center gap-2 text-[10px] text-[var(--text-faint)]">
								<span className="rounded bg-[var(--panel-2)] px-1.5 py-0.5 font-semibold uppercase">
									{item.source}
								</span>
								<span>{item.date_str}</span>
								<span className="ml-auto flex items-center gap-1">
									<SentimentDot score={item.score} />
									<span className="capitalize">{item.sentiment}</span>
								</span>
							</div>
							<div className="text-sm font-semibold leading-snug text-[var(--text)] hover:text-[var(--accent)]">
								{item.title}
							</div>
							<div className="mt-2 flex flex-wrap items-center gap-1">
								<span
									className="rounded px-1.5 py-0.5 text-[10px] font-bold"
									style={{
										color: item.color,
										backgroundColor: `${item.color}18`,
									}}
								>
									{item.label}
								</span>
								{item.tags.slice(0, 5).map((t) => (
									<span
										key={t}
										className="rounded bg-[var(--panel-2)] px-1.5 py-0.5 font-mono text-[10px] text-[var(--text-dim)]"
									>
										{t}
									</span>
								))}
							</div>
						</a>
					))}
				</div>
			)}
		</Shell>
	);
}

function SentimentDot({ score }: { score: number }) {
	const tone =
		score > 0 ? "var(--up)" : score < 0 ? "var(--down)" : "var(--text-faint)";
	return (
		<span
			className="inline-block h-2 w-2 rounded-full"
			style={{ backgroundColor: tone }}
			title={`sentiment ${score}`}
		/>
	);
}

text:
"use client";

import { useState } from "react";
import { api, fmtNum, type ValidatorResult } from "@/lib/api";
import Shell from "@/components/Shell";
import { SectionHeader, Skeleton, Spinner, StatCard } from "@/components/ui";

const INTENT_TONE = (intent: string): string => {
	if (/SILENT EXIT|DISTRIBUTION|ABANDONED|MARKDOWN|CHURN/.test(intent))
		return "text-[var(--down)]";
	if (/ACCUM|MARKUP|ABSORPTION|GUARDING|SILENT/.test(intent))
		return "text-[var(--up)]";
	if (/LOW VOL|NORMAL/.test(intent)) return "text-[var(--text-faint)]";
	return "text-[var(--gold)]";
};

export default function ValidatorPage() {
	const [ticker, setTicker] = useState("BBRI");
	const [result, setResult] = useState<ValidatorResult | null>(null);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);

	const run = async () => {
		setLoading(true);
		setError(null);
		try {
			const res = await api.get<ValidatorResult>(`/api/validator/${ticker}`);
			setResult(res);
		} catch (e) {
			setError(e instanceof Error ? e.message : String(e));
		} finally {
			setLoading(false);
		}
	};

	const s = result?.summary;

	return (
		<Shell>
			<SectionHeader
				title="Bandarmology Validator"
				subtitle="Smart-money detector — VWAP phase, institutional flow, hidden intent radar (IHSG)"
			/>

			<div className="mb-6 flex items-end gap-3">
				<label className="text-[11px] text-[var(--text-faint)]">
					Ticker
					<input
						value={ticker}
						onChange={(e) => setTicker(e.target.value.toUpperCase())}
						onKeyDown={(e) => e.key === "Enter" && void run()}
						className="panel-2 mt-1 w-36 px-3 py-2 font-mono text-sm text-[var(--text)] focus:outline-none"
					/>
				</label>
				<button
					onClick={() => void run()}
					disabled={loading}
					className="rounded-md bg-[var(--accent)] px-5 py-2 text-sm font-semibold text-black hover:opacity-90 disabled:opacity-50"
				>
					{loading ? <Spinner label="Analyzing…" /> : "Analyze"}
				</button>
			</div>

			{error && (
				<div className="panel mb-4 border-[var(--down)]/40 p-4 text-sm text-[var(--down)]">
					{error}
				</div>
			)}
			{result?.error && (
				<div className="panel mb-4 p-4 text-sm text-[var(--down)]">
					{result.error}
				</div>
			)}
			{loading && <Skeleton className="h-72" />}

			{s && !loading && (
				<>
					<div className="mb-6 grid grid-cols-2 gap-4 lg:grid-cols-4">
						<StatCard
							label="Close"
							value={fmtNum(s.close)}
							tone={s.change_pct >= 0 ? "up" : "down"}
							sub={`${s.change_pct >= 0 ? "+" : ""}${s.change_pct.toFixed(2)}% today`}
						/>
						<StatCard
							label="Bandar Phase"
							value={<span className="text-sm">{s.bandar_phase.phase}</span>}
							sub={`VWAP gap ${s.bandar_phase.gap_pct > 0 ? "+" : ""}${s.bandar_phase.gap_pct.toFixed(2)}%`}
							tone={
								s.bandar_phase.gap_pct < -2
									? "up"
									: s.bandar_phase.gap_pct > 2
										? "down"
										: "accent"
							}
						/>
						<StatCard
							label="Institutional Flow"
							value={s.inst_flow}
							tone={s.inst_flow === "NET BUY" ? "up" : "down"}
							sub={`5-day smoothed ${fmtNum(s.inst_flow_ma, 0)}`}
						/>
						<StatCard
							label="Current Intent"
							value={
								<span className={`text-sm ${INTENT_TONE(s.current_intent)}`}>
									{s.current_intent}
								</span>
							}
							sub={`RSI ${fmtNum(s.rsi)} · Confirmed Flow ${s.conf_flow_index}/4`}
						/>
					</div>

					<div className="mb-6 grid grid-cols-1 gap-6 lg:grid-cols-3">
						<div className="panel p-4">
							<h2 className="mb-3 text-sm font-bold uppercase tracking-wider text-[var(--text-dim)]">
								Liquidity & Flow
							</h2>
							<Row k="Liquidity" v={s.liquidity.status} />
							<Row k="Avg Value/Day" v={s.liquidity.avg_value_display} />
							<Row
								k="Analysis Mode"
								v={
									s.small_cap_mode
										? "Small-cap optimized"
										: "Standard (big/mid)"
								}
							/>
							<Row k="NVI (smart money)" v={s.nvi_status} />
							<Row k="Dormant Index" v={`${s.dormant_index.toFixed(1)}/100`} />
							<Row
								k="Confirmed Flow"
								v={`${s.conf_flow_index}/4 (${s.conf_flow_label})`}
							/>
						</div>

						<div className="panel p-4 lg:col-span-2">
							<h2 className="mb-3 text-sm font-bold uppercase tracking-wider text-[var(--text-dim)]">
								Intent Radar — last {result?.radar?.length ?? 0} sessions
							</h2>
							<div className="max-h-[340px] overflow-y-auto">
								<table className="w-full text-sm">
									<thead className="sticky top-0 bg-[var(--panel)]">
										<tr className="border-b border-[var(--border)] text-left text-[11px] uppercase tracking-wider text-[var(--text-faint)]">
											<th className="pb-2">Date</th>
											<th className="pb-2 text-right">Close</th>
											<th className="pb-2 text-right">Chg %</th>
											<th className="pb-2 text-right">VWAP</th>
											<th className="pb-2 text-right">Flow</th>
											<th className="pb-2 text-right">Conf</th>
											<th className="pb-2">Intent</th>
										</tr>
									</thead>
									<tbody>
										{result?.radar?.map((r) => (
											<tr
												key={r.date}
												className="border-b border-[var(--border)]/50"
											>
												<td className="tabular py-1.5 font-mono text-xs">
													{r.date}
												</td>
												<td className="tabular py-1.5 text-right font-mono text-xs">
													{fmtNum(r.close)}
												</td>
												<td
													className={`tabular py-1.5 text-right font-mono text-xs ${r.change_pct >= 0 ? "text-[var(--up)]" : "text-[var(--down)]"}`}
												>
													{r.change_pct > 0 ? "+" : ""}
													{r.change_pct.toFixed(1)}%
												</td>
												<td className="tabular py-1.5 text-right font-mono text-xs">
													{fmtNum(r.vwap, 0)}
												</td>
												<td
													className={`tabular py-1.5 text-right font-mono text-xs ${r.inst_flow != null && r.inst_flow >= 0 ? "text-[var(--up)]" : "text-[var(--down)]"}`}
												>
													{r.inst_flow != null
														? r.inst_flow >= 0
															? "▲"
															: "▼"
														: "—"}
												</td>
												<td className="tabular py-1.5 text-right font-mono text-xs">
													{r.conf_flow}/4
												</td>
												<td
													className={`py-1.5 text-xs ${INTENT_TONE(r.intent)}`}
												>
													{r.intent}
												</td>
											</tr>
										))}
									</tbody>
								</table>
							</div>
						</div>
					</div>
				</>
			)}

			{!result && !loading && (
				<div className="panel grid-texture p-16 text-center text-sm text-[var(--text-faint)]">
					Enter a ticker to run the bandarmology analysis —
					accumulation/distribution phase, institutional flow, and the
					hidden-intent radar will render here.
				</div>
			)}
		</Shell>
	);
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
	return (
		<div className="flex items-center justify-between border-b border-[var(--border)]/50 py-1.5 last:border-0">
			<span className="text-xs text-[var(--text-faint)]">{k}</span>
			<span className="text-right font-mono text-xs font-semibold text-[var(--text)]">
				{v}
			</span>
		</div>
	);
}

